Subject: Re: Helios onboarding: MVP scope and next steps

Marta — looping in a quick dev note and an SDK sample for your engineering lead. Below is a minimal Node.js example showing the recommended timeout & retry wrapper we run in our examples repo. It assumes API key auth via the REDWOOD_API_KEY env var.

--- sample snippet start ---
const fetch = require('node-fetch');

async function callRedwood(payload, attempts = 0) {
  const MAX_RETRIES = 3;
  const BACKOFF_BASE_MS = 200;

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 12000); // 12s read timeout for chat

    const res = await fetch(process.env.REDWOOD_ENDPOINT + '/v1/generate', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${process.env.REDWOOD_API_KEY}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload),
      signal: controller.signal
    });
    clearTimeout(timeout);

    if (res.status === 429 && attempts < MAX_RETRIES) {
      const backoff = BACKOFF_BASE_MS * Math.pow(2, attempts) + Math.floor(Math.random() * 200);
      await new Promise(r => setTimeout(r, backoff));
      return callRedwood(payload, attempts + 1);
    }

    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    if (attempts < MAX_RETRIES && err.name !== 'AbortError') {
      const backoff = BACKOFF_BASE_MS * Math.pow(2, attempts);
      await new Promise(r => setTimeout(r, backoff));
      return callRedwood(payload, attempts + 1);
    }
    throw err;
  }
}

module.exports = { callRedwood };
--- sample snippet end ---

Notes: 1) Use streaming where possible to reduce perceived latency; 2) Mirror traffic to Redwood in shadow mode for 48-72 hours before cutover; 3) Instrument token-level latency in your logs so we can troubleshoot kernel/seqlen hotspots together.

Let me know who from Helios will be on the kickoff (platform lead + one backend engineer recommended).

